pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _run(uint256 seedDrugs) internal {
        try c.seedMarket(seedDrugs) {} catch { return; }
        try c.getFreeKilo() {} catch { return; }
        uint256 kilos;
        try c.getMyKilo() returns (uint256 __r) { kilos = __r; } catch { return; }
        uint256 starting;
        try c.STARTING_KILOS() returns (uint256 __r) { starting = __r; } catch { return; }
        uint256 since;
        try c.getDrugsSinceLastCollect(address(this)) returns (uint256 __r) { since = __r; } catch { return; }
        assertTrue(kilos == starting && since == 0);
    }

    function testFuzz_run(uint256 seedDrugs) public {
        _run(seedDrugs);
    }

    receive() external payable {}
}
